// Build for Nsight System analysis, only run 1 single-block and multi-block to avoid bunchs of kernels.
// Generated By ChatGPT, has already been reviewed by Zhehang.

#include "cuda/cuda_ops.cuh"

#include <cuda_runtime.h>

#include <iostream>
#include <random>
#include <string>
#include <vector>


void check_cuda(
    cudaError_t result,
    const char* message
)
{
    if(result != cudaSuccess)
    {
        std::cerr
            << "CUDA Error: "
            << message
            << std::endl;

        std::cerr
            << cudaGetErrorString(result)
            << std::endl;

        std::exit(EXIT_FAILURE);
    }
}


   
// ./build/cuda_attention_softmax_profile 4096 single    ||       ./build/cuda_attention_softmax_profile 4096 multi 4
int main(int argc, char** argv)   // argv是用来存储命令行中的数值的，argc代表argv的个数
{
    // ============================
    // Arguments
    // ============================

    int seq_len = 4096;

    int blocks_per_row = 4;

    std::string mode = "both";


    if(argc >= 2)
    {
        seq_len = std::stoi(argv[1]);   // stoi will transfer string to int
    }


    if(argc >= 3)
    {
        mode = argv[2];
    }


    if(argc >= 4)
    {
        blocks_per_row = std::stoi(argv[3]);
    }


    if(
        mode != "single" &&
        mode != "multi" &&
        mode != "both"
    )
    {
        std::cerr
            << "Usage: "
            << argv[0]
            << " <seq_len> "
            << "[single|multi|both] "
            << "[blocks_per_row]"
            << std::endl;

        return 1;
    }



    std::cout
        << "===================================="
        << std::endl;

    std::cout
        << "Attention Softmax Profiling"
        << std::endl;

    std::cout
        << "seq_len        = "
        << seq_len
        << std::endl;

    std::cout
        << "mode           = "
        << mode
        << std::endl;

    std::cout
        << "blocks_per_row = "
        << blocks_per_row
        << std::endl;

    std::cout
        << "===================================="
        << std::endl;



    // ============================
    // Memory sizes
    // ============================

    const std::size_t elements =
        static_cast<std::size_t>(seq_len)
        * seq_len;


    const std::size_t matrix_bytes =
        elements * sizeof(float);


    const std::size_t partial_elements =
        static_cast<std::size_t>(seq_len)
        * blocks_per_row;


    const std::size_t partial_bytes =
        partial_elements * sizeof(float);


    const std::size_t row_bytes =
        static_cast<std::size_t>(seq_len)
        * sizeof(float);



    // ============================
    // Host input
    // ============================

    std::vector<float> scores(elements);


    std::mt19937 generator(42);

    std::uniform_real_distribution<float>
        distribution(-5.0f, 5.0f);


    for(float& value : scores)
    {
        value = distribution(generator);
    }



    // ============================
    // Device pointers
    // ============================

    float* d_scores = nullptr;

    float* d_single_weights = nullptr;
    float* d_multi_weights = nullptr;

    float* d_partial_max = nullptr;
    float* d_partial_sum = nullptr;

    float* d_row_max = nullptr;
    float* d_row_sum = nullptr;



    // ============================
    // Allocation
    // ============================

    check_cuda(
        cudaMalloc(
            &d_scores,
            matrix_bytes
        ),
        "cudaMalloc d_scores"
    );


    check_cuda(
        cudaMalloc(
            &d_single_weights,
            matrix_bytes
        ),
        "cudaMalloc d_single_weights"
    );


    check_cuda(
        cudaMalloc(
            &d_multi_weights,
            matrix_bytes
        ),
        "cudaMalloc d_multi_weights"
    );


    check_cuda(
        cudaMalloc(
            &d_partial_max,
            partial_bytes
        ),
        "cudaMalloc d_partial_max"
    );


    check_cuda(
        cudaMalloc(
            &d_partial_sum,
            partial_bytes
        ),
        "cudaMalloc d_partial_sum"
    );


    check_cuda(
        cudaMalloc(
            &d_row_max,
            row_bytes
        ),
        "cudaMalloc d_row_max"
    );


    check_cuda(
        cudaMalloc(
            &d_row_sum,
            row_bytes
        ),
        "cudaMalloc d_row_sum"
    );



    // ============================
    // Copy input
    // ============================

    check_cuda(
        cudaMemcpy(
            d_scores,
            scores.data(),
            matrix_bytes,
            cudaMemcpyHostToDevice
        ),
        "Copy scores H2D"
    );



    // ============================
    // Warmup
    // ============================

    const int warmup_runs = 10;


    std::cout
        << "Warmup..."
        << std::endl;


    for(int i = 0;
        i < warmup_runs;
        i++)
    {
        if(
            mode == "single" ||
            mode == "both"
        )
        {
            cuda_attention_softmax(
                d_scores,
                d_single_weights,
                seq_len
            );
        }


        if(
            mode == "multi" ||
            mode == "both"
        )
        {
            cuda_attention_softmax_multiblock(
                d_scores,
                d_multi_weights,

                d_partial_max,
                d_partial_sum,

                d_row_max,
                d_row_sum,

                seq_len,
                blocks_per_row
            );
        }
    }


    check_cuda(
        cudaDeviceSynchronize(),
        "Warmup synchronization"
    );



    // ============================
    // Profile Single Block
    // ============================

    if(
        mode == "single" ||
        mode == "both"
    )
    {
        std::cout
            << "PROFILE_BEGIN_SINGLE"
            << std::endl;


        cuda_attention_softmax(
            d_scores,
            d_single_weights,
            seq_len
        );


        check_cuda(
            cudaGetLastError(),
            "Single-block kernel launch"
        );


        check_cuda(
            cudaDeviceSynchronize(),
            "Single-block synchronization"
        );


        std::cout
            << "PROFILE_END_SINGLE"
            << std::endl;
    }



    // ============================
    // Profile Multi Block
    // ============================

    if(
        mode == "multi" ||
        mode == "both"
    )
    {
        std::cout
            << "PROFILE_BEGIN_MULTI"
            << std::endl;


        cuda_attention_softmax_multiblock(
            d_scores,
            d_multi_weights,

            d_partial_max,
            d_partial_sum,

            d_row_max,
            d_row_sum,

            seq_len,
            blocks_per_row
        );


        check_cuda(
            cudaGetLastError(),
            "Multi-block kernel launch"
        );


        check_cuda(
            cudaDeviceSynchronize(),
            "Multi-block synchronization"
        );


        std::cout
            << "PROFILE_END_MULTI"
            << std::endl;
    }



    // ============================
    // Cleanup
    // ============================

    cudaFree(d_scores);

    cudaFree(d_single_weights);
    cudaFree(d_multi_weights);

    cudaFree(d_partial_max);
    cudaFree(d_partial_sum);

    cudaFree(d_row_max);
    cudaFree(d_row_sum);



    std::cout
        << "Profiling completed."
        << std::endl;


    return 0;
}